        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                return False, "CSV file is empty"
            # Check if any row has at least one column
            for row in header:
                if len(row) > 0:
                    return True, "CSV has header with columns"
    except Exception:
        return False, f"Cannot read CSV: {filepath}"

    return True, "CSV has header with columns"

