def check_json_has_entries(filepath):
    """Check if a JSON file has at least one entry."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()
            if len(content) == 0:
                return False, "File is empty"
            # Try to parse JSON and check for entries
            data = json.loads(content)
            if isinstance(data, list) and len(data) > 0:
                return True, f"JSON has {len(data)} entries"
    except Exception:
        return False, f"Cannot parse JSON: {filepath}"

    return True, "JSON has entries"

def check_csv_has_valid_row(filepath, expected_column):
    """Check if CSV has at least one valid row with the expected column."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            first_row = next(reader, None)
            if first_row is None:
                return False, "CSV file is empty"
            # Check if any row has the expected column with data
            for row in first_row:
                if expected_column in row and len(row[expected_column]) > 0:
                    return True, "CSV has valid data for expected column"
    except Exception:
        return False, f"Cannot read CSV: {filepath}"

    return True, "CSV has valid data for expected column"

def run_check(check, filepath):
    """Run a single check and return (passed, message)."""
    passed, message = check
    return passed, message

def main():
    summary = []

    # Validate all required outputs
    for output in OUTPUTS_TO_VALIDATE:
        filepath = os.path.join(OUTPUTS_DIR, output)
        passed, message = run_check(CHECKS, filepath)
        summary.append({
