    for output in REQUIRED_OUTPUTS:
        filepath = os.path.join(OUTPUTS_DIR, output)
        passed, message = run_check(CHECKS, filepath)
        summary.append({
            "check_name": CHECKS[0]["check_name"],
            "passed": passed,
            "message": message
        })

    # Write summary JSON
    output_path = os.path.join(WORKSPACE_ROOT, "outputs", "t14_validation_summary.json")
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(summary, f, indent=2)

    print(f"Validation complete. Summary written to {output_path}")
    return 0

if __name__ == "__main__":
    sys.exit(main())
